Copy the workbook, build a code-to-month map from the codes2/month ranges (defaulting to E3:E14 and F3:F14), then for each A3:A14 extract the underscore-delimited month token and write the mapped month to B3:B14. Use digit-boundary fallbacks so digits inside the year are not matched. Save the output workbook with plain values.

```python
import shutil, re, openpyxl
from openpyxl.utils import range_boundaries

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active if wb.active is not None else wb.worksheets[0]
vws = vals[ws.title]

def norm_code(x):
    if x is None:
        return None
    s = str(x).strip()
    if not s:
        return None
    try:
        f = float(s)
        if f.is_integer() and 1 <= int(f) <= 12:
            return f"{int(f):02d}"
    except Exception:
        pass
    if s.isdigit():
        n = int(s)
        if 1 <= n <= 12:
            return f"{n:02d}"
    return s

def build_mapping(codes, months):
    m = {}
    for c, mo in zip(codes, months):
        nc = norm_code(c)
        if nc is None or mo is None:
            continue
        ms = str(mo).strip()
        m[nc] = ms
        raw = str(c).strip()
        if raw and raw != nc:
            m[raw] = ms
    return m

def get_column_values(name, default_col):
    try:
        dn = wb.defined_names.get(name)
        if dn is None:
            raise KeyError(name)
        ref = dn.value
        sheet_name = ws.title
        if '!' in ref:
            sheet_part, ref = ref.split('!', 1)
            sheet_name = sheet_part.strip().strip("'")
        min_col, min_row, max_col, max_row = range_boundaries(ref)
        v = vals[sheet_name]
        return [v.cell(row=r, column=min_col).value for r in range(min_row, max_row + 1)]
    except Exception:
        return [vws.cell(row=r, column=default_col).value for r in range(3, 15)]

mapping = {}
codes = get_column_values('codes2', 5)
months = get_column_values('month', 6)

if len(codes) == len(months):
    mapping = build_mapping(codes, months)

if not mapping:
    codes = [vws.cell(row=r, column=5).value for r in range(3, 15)]
    months = [vws.cell(row=r, column=6).value for r in range(3, 15)]
    mapping = build_mapping(codes, months)

def find_month(a):
    if a is None:
        return None
    s = str(a).strip()
    if not s:
        return None

    parts = s.split('_')
    if len(parts) >= 2:
        tok = parts[1].strip()
        if tok in mapping:
            return mapping[tok]
        nc = norm_code(tok)
        if nc is not None and nc in mapping:
            return mapping[nc]

    for length in (2, 1):
        for code, month in mapping.items():
            if code.isdigit() and len(code) == length:
                if re.search(r'(?<!\d)' + re.escape(code) + r'(?!\d)', s):
                    return month

    return None

for r in range(3, 15):
    a = vws.cell(row=r, column=1).value
    m = find_month(a)
    ws.cell(row=r, column=2).value = m
    print(r, repr(a), repr(m))

wb.save(OUT)
